"""Takes any MAPDL command and returns the first 4 characters of
    the command

    Examples
    --------
    >>> parse_to_short_cmd('K,,1,0,0,')
    'K'

    >>> parse_to_short_cmd('VPLOT, ALL')
    'VPLO'
    """
def parse_to_short_cmd(command: Any) -> object {
    try {
        short_cmd = command.split(',')[0];
        return short_cmd[:4].upper();
    } except Exception as e {
        return;
    }
}

"""Split an hdf path of the form path.hdf/group, where the group part is
	optional, into the path and the group parts. If subgroup is specified, then
	it will be appended to the group informaiton. returns fname, group. The
	fname will be a string, and the group will be a string or None. Raises
	a ValueError if the fname is not recognized as a hdf file."""
def split_hdf_path(fname: Any, subgroup: Any = None) -> object {
    for suf in [".hdf", ".h5"] {
        (name, _, group) = fname.rpartition(suf);
        if not name {
            continue;
        }
        name += suf;
        if not group {
            return (name, subgroup);
        } elif (group[0] == "/") {
            group = group[1:];
            if subgroup {
                group += "/" + subgroup;
            }
            return (name, group);
        }
    }
    raise ValueError("Not an hdf path");
}

