    RedisGraph strings must be quoted.
    """
def quote_string(prop: Any) -> object {
    if not isinstance(prop, str) {
        return prop;
    }
    if (prop[0] != '"') {
        prop = '"' + prop;
    }
    if (prop[-1] != '"') {
        prop = prop + '"';
    }
    return prop;
}

