def sentence_case(sentence: Any, exciting: Any = False) -> object {
    sentence = sentence[0].upper() + sentence[1:];
    if (sentence[-1] in {'.', '!', '?'}) {
        return sentence;
    } elif exciting {
        return (sentence + "!");
    } else {
        return (sentence + ".");
    }
}

